//! Current iOS MelSpecTests numerical/cache cases, using captured independent
//! Python/HF/Kaldi goldens. No oracle is generated by the implementation.
//!
//! GigaAM/Nemotron use published preprocessor ONNX graphs on Android (as their
//! exporter contracts explicitly state). Their values here grade the generic
//! host MelSpec axes; the actual graph doors remain in the model contract gates.
use ferment_engine_audio::derived_cache::{DerivedFileCache, DerivedSource, nonce, request_hash};
use ferment_engine_audio::mel_spec::{
    Compression, FilterNorm, FilterShape, MelRequest, Normalization, Padding, PreEmphasis, Scale,
    Spectrum, TablePrecision, Window,
};
use ferment_engine_audio::{MelSpec, MelSpectrogram};
use ferment_engine_processors::{audio_event_detector, beatthis, dasheng, musichighlighter};
use std::path::PathBuf;

fn floats(root_variable: &str, relative: &str) -> Vec<f32> {
    let root = PathBuf::from(std::env::var_os(root_variable).unwrap_or_else(|| {
        panic!("{root_variable} must select the immutable captured fixture tree")
    }));
    let bytes = std::fs::read(root.join(relative)).unwrap_or_else(|e| panic!("{relative}: {e}"));
    assert_eq!(bytes.len() % 4, 0, "{relative} is not float32 PCM");
    bytes
        .chunks_exact(4)
        .map(|v| f32::from_le_bytes(v.try_into().unwrap()))
        .collect()
}

fn fixture(relative: &str) -> Vec<f32> {
    floats("FERMENT_ENGINE_FIXTURES_DIR", relative)
}

fn gigaam_audio() -> Vec<f32> {
    floats(
        "FERMENT_MODELS_EXPORT_DIR",
        "gigaam/goldens/gigaam_audio_in.f32",
    )
}

fn worst(actual: &[f32], expected: &[f32]) -> f32 {
    assert_eq!(actual.len(), expected.len());
    assert!(actual.iter().all(|v| v.is_finite()));
    assert!(expected.iter().all(|v| v.is_finite()));
    actual
        .iter()
        .zip(expected)
        .map(|(a, b)| (a - b).abs())
        .fold(0.0, f32::max)
}

fn gigaam() -> MelSpec {
    MelSpec {
        sample_rate: 16000.0,
        fft_size: 320,
        hop_length: 160,
        mel_bands: 64,
        f_min: 0.0,
        f_max: 8000.0,
        input_scale: 1.0,
        padding: Padding::None,
        window: Window::HannPeriodic,
        window_length: None,
        dc_removal: false,
        pre_emphasis: None,
        spectrum: Spectrum::Power,
        normalization: Normalization::None,
        mel_scale: Scale::Htk,
        filter_shape: FilterShape::HertzLinear,
        filter_norm: FilterNorm::None,
        table_precision: TablePrecision::Bfloat16,
        compression: Compression::LogClamped {
            floor: 1e-9,
            ceiling: 1e9,
        },
    }
}

fn nemo() -> MelSpec {
    MelSpec {
        fft_size: 512,
        mel_bands: 128,
        padding: Padding::Constant,
        window: Window::HannSymmetric,
        window_length: Some(400),
        pre_emphasis: Some(PreEmphasis::Signal { alpha: 0.97 }),
        mel_scale: Scale::Slaney,
        filter_norm: FilterNorm::SlaneyArea,
        table_precision: TablePrecision::Float32,
        compression: Compression::Log {
            guard: 2.0_f32.powi(-24),
        },
        ..gigaam()
    }
}

struct Root(PathBuf);
impl Root {
    fn new() -> Self {
        Self(std::env::temp_dir().join(format!("current-mel-spec-{}", nonce())))
    }
    fn cache(&self) -> DerivedFileCache {
        DerivedFileCache::new(self.0.clone(), 1 << 30).unwrap()
    }
}
impl Drop for Root {
    fn drop(&mut self) {
        let _ = std::fs::remove_dir_all(&self.0);
    }
}

#[test]
#[ignore = "requires immutable captured Python reference"]
fn beat_this_spec_matches_the_current_python_reference() {
    let samples = fixture("pipeline_test_audio.bin");
    let expected = fixture("pipeline_ref_mel.bin");
    let actual = beatthis::config::MEL_SPEC.compute(&samples).unwrap();
    assert!(actual.frame_count().abs_diff(expected.len() / 128) <= 1);
    let common = actual.frame_count().min(expected.len() / 128) * 128;
    assert!(common > 0);
    let delta = worst(&actual.values[..common], &expected[..common]);
    assert!(delta < 0.05, "BeatThis Python reference: {delta}");
}

#[test]
fn empty_audio_has_no_frames() {
    let frames = beatthis::config::MEL_SPEC.compute(&[]).unwrap();
    assert_eq!(frames.frame_count(), 0);
    assert!(frames.values.is_empty());
    assert!(frames.bands_major(None).is_empty());
}

#[test]
#[ignore = "requires immutable captured music input"]
fn perform_caches_by_exact_spec_and_hits_the_landed_bytes() {
    let root = Root::new();
    let cache = root.cache();
    let samples = fixture("pipeline_test_audio.bin");
    let source = DerivedSource::new("fixture");
    let spec = beatthis::config::MEL_SPEC;
    let first = spec.perform(&samples, Some(&source), Some(&cache)).unwrap();
    assert_eq!(first, spec.compute(&samples).unwrap());
    assert_eq!(cache.total_bytes(), (first.values.len() * 4) as u64);
    let second = spec
        .perform(&vec![0.5; samples.len()], Some(&source), Some(&cache))
        .unwrap();
    assert_eq!(
        second, first,
        "a hit reads the file, not the caller's new samples"
    );
    let changed = MelSpec {
        compression: Compression::Log1p { multiplier: 999.0 },
        ..spec
    };
    let third = changed
        .perform(&samples, Some(&source), Some(&cache))
        .unwrap();
    assert_ne!(third, first);
    assert_eq!(cache.total_bytes(), (2 * first.values.len() * 4) as u64);
}

#[test]
#[ignore = "requires immutable captured music input"]
fn perform_without_a_source_or_cache_just_computes() {
    let root = Root::new();
    let cache = root.cache();
    let samples = fixture("pipeline_test_audio.bin");
    let source = DerivedSource::new("fixture");
    let spec = beatthis::config::MEL_SPEC;
    let expected = spec.compute(&samples).unwrap();
    assert_eq!(
        spec.perform(&samples, Some(&source), None).unwrap(),
        expected
    );
    assert_eq!(spec.perform(&samples, None, None).unwrap(), expected);
    assert_eq!(
        spec.perform(&samples, None, Some(&cache)).unwrap(),
        expected
    );
    assert_eq!(
        cache.total_bytes(),
        0,
        "no source identity means no persistent artifact"
    );
}

#[test]
fn spec_is_a_stable_cache_key_and_distinguishes_the_other_frontend() {
    let key = || MelRequest {
        source: DerivedSource::new("s"),
        spec: beatthis::config::MEL_SPEC,
    };
    assert_eq!(request_hash(&key()).unwrap(), request_hash(&key()).unwrap());
    assert_ne!(
        request_hash(&key()).unwrap(),
        request_hash(&MelRequest {
            spec: musichighlighter::config::MEL_SPEC,
            ..key()
        })
        .unwrap()
    );
}

#[test]
#[ignore = "requires captured torch checkpoint input and golden"]
fn gigaam_spec_matches_torch_and_transposes_with_zero_padding() {
    for (source, samples, golden) in [
        (
            "exporter",
            gigaam_audio(),
            floats(
                "FERMENT_MODELS_EXPORT_DIR",
                "gigaam/goldens/gigaam_mel_out.f32",
            ),
        ),
        (
            "current-ios",
            fixture("GigaAM/gigaam_audio_in.bin"),
            fixture("GigaAM/gigaam_mel_out.bin"),
        ),
    ] {
        let spec = gigaam();
        assert_eq!(samples.len(), 240_000);
        assert_eq!(spec.frame_count(samples.len()), 1499);
        let frames = spec.compute(&samples).unwrap();
        assert_eq!(frames.frame_count(), 1499);
        assert_eq!(frames.bands, 64);
        let transposed = frames.bands_major(None);
        let delta = worst(&transposed, &golden);
        eprintln!("[current-gigaam-mel] {source} max |delta| {delta}");
        assert!(delta < 1e-3, "GigaAM torch golden: {delta}");
        assert_eq!(transposed[3 * 1499 + 7], frames.frame(7)[3]);
        let padded = frames.bands_major(Some(1500));
        assert_eq!(padded.len(), 64 * 1500);
        assert_eq!(padded[5 * 1500 + 1498], frames.frame(1498)[5]);
        assert_eq!(padded[5 * 1500 + 1499], 0.0);
    }
}

#[test]
#[ignore = "requires captured checkpoint bf16 window and filterbank"]
fn gigaam_tables_are_the_checkpoints_own() {
    let window = fixture("GigaAM/gigaam_window_320.f32");
    let filterbank = fixture("GigaAM/gigaam_fb_161x64.f32");
    assert_eq!(window.len(), 320);
    assert_eq!(filterbank.len(), 161 * 64);
    let engine = MelSpectrogram::new(gigaam()).unwrap();
    assert_eq!(engine.window(), window.as_slice());
    let ours = engine.filterbank();
    let mut flipped = 0;
    for bin in 0..161 {
        for band in 0..64 {
            let a = ours[band * 161 + bin];
            let b = filterbank[bin * 64 + band];
            if a != b {
                flipped += 1;
                assert!(
                    (a - b).abs() <= a.abs().max(b.abs()) * 0.0079 + 1e-6,
                    "filterbank bin {bin} band {band}: {a} vs {b}"
                );
            }
        }
    }
    assert!(flipped <= 8, "{flipped} bf16 entries rounded the other way");
}

#[test]
#[ignore = "requires captured HF Nemotron and GigaAM input fixtures"]
fn nemo_spec_matches_hf_at_both_window_lengths() {
    for (samples, name, count) in [
        (
            fixture("Nemotron/nemotron_mel_chunk_in.f32"),
            "Nemotron/nemotron_mel_chunk_out.f32",
            57,
        ),
        (
            // HF generated this output from the iOS fixture, not the
            // exporter's different speech sample with the same stem.
            fixture("GigaAM/gigaam_audio_in.bin")[16000..48000].to_vec(),
            "Nemotron/nemotron_mel_2s_out.f32",
            201,
        ),
    ] {
        let golden = fixture(name);
        assert_eq!(golden.len(), count * 128);
        let spec = nemo();
        assert_eq!(spec.frame_count(samples.len()), count);
        let frames = spec.compute(&samples).unwrap();
        assert_eq!(frames.frame_count(), count);
        let mut zeroed = frames.values;
        zeroed[(count - 1) * 128..].fill(0.0);
        let delta = worst(&zeroed, &golden);
        eprintln!("[current-nemo-mel] {name} max |delta| {delta}");
        assert!(delta < 5e-4, "{name}: {delta}");
    }
}

#[test]
#[ignore = "requires captured checkpoint audio"]
fn absolute_decibels_are_scaled_clamped_log_and_floor_per_call() {
    let samples = fixture("GigaAM/gigaam_audio_in.bin")[0..32000].to_vec();
    let spec = MelSpec {
        table_precision: TablePrecision::Float32,
        compression: Compression::DecibelsAbsolute { amin: 1e-10 },
        ..gigaam()
    };
    let decibels = spec.compute(&samples[..32000]).unwrap();
    let natural = MelSpec {
        compression: Compression::LogClamped {
            floor: 1e-10,
            ceiling: f32::MAX,
        },
        ..spec
    }
    .compute(&samples[..32000])
    .unwrap();
    let expected = natural
        .values
        .iter()
        .map(|v| 10.0 * v / 10.0_f32.ln())
        .collect::<Vec<_>>();
    assert!(worst(&decibels.values, &expected) < 1e-4);
    let peak = decibels.values.iter().copied().fold(f32::MIN, f32::max);
    let low = decibels.values.iter().copied().fold(f32::MAX, f32::min);
    let clamped = decibels.clone().clamped_below_max_by(120.0);
    assert!(
        (clamped.values.iter().copied().fold(f32::MAX, f32::min) - low.max(peak - 120.0)).abs()
            < 1e-5
    );
    assert_eq!(
        clamped.values.iter().copied().fold(f32::MIN, f32::max),
        peak
    );
    assert!(
        decibels
            .clamped_below_max_by(1.0)
            .values
            .iter()
            .all(|v| *v >= peak - 1.0 - 1e-5)
    );
}

#[test]
#[ignore = "requires captured independent Dasheng speech frontend"]
fn dasheng_speech_frontend_keeps_the_uniform_current_ios_bound() {
    let samples = fixture("Dasheng/dasheng_audio_in.bin");
    let golden = fixture("Dasheng/dasheng_mel_out.f32");
    assert_eq!(samples.len(), 160_000);
    assert_eq!(golden.len(), 64 * 1001);
    let frames = dasheng::frontend::mel(&samples).unwrap();
    assert_eq!(frames.frame_count(), 1001);
    let delta = worst(&frames.bands_major(None), &golden);
    eprintln!("[current-dasheng-mel] uniform speech bound max |delta| {delta}");
    assert!(delta < 1e-3, "current Swift speech bound: {delta}");
}

#[test]
fn kaldi_spec_floors_silence_at_epsilon() {
    let spec = audio_event_detector::config::MEL_SPEC;
    assert_eq!(spec.frame_count(1600), 8);
    assert_eq!(spec.frame_count(400), 1);
    assert_eq!(spec.frame_count(399), 0);
    let frames = spec.compute(&[0.0; 1600]).unwrap();
    assert_eq!(frames.frame_count(), 8);
    assert_eq!(frames.bands, 80);
    assert!((f32::EPSILON.ln() - -15.942385).abs() < 1e-6);
    assert!(frames.values.iter().all(|v| (v - -15.942385).abs() < 1e-5));
}

#[test]
fn kaldi_spec_matches_the_independent_library_impulse() {
    let mut samples = [0.0; 1600];
    samples[100] = 1.0 / 32768.0;
    let frames = audio_event_detector::config::MEL_SPEC
        .compute(&samples)
        .unwrap();
    let first = frames.frame(0);
    assert_eq!(first.len(), 80);
    for (bin, expected) in [
        (0, -8.541_766),
        (10, -5.397_73),
        (40, -0.9330384),
        (79, 2.3095396),
    ] {
        assert!(
            (first[bin] - expected).abs() < 1e-4,
            "frame 0 bin {bin}: {} vs {expected}",
            first[bin]
        );
    }
    assert!((first.iter().sum::<f32>() / 80.0 - -1.5555189).abs() < 1e-4);
    assert!(
        frames
            .frame(1)
            .iter()
            .all(|v| (v - -15.942385).abs() < 1e-5)
    );
}
